/** Types for the bundled demo recordings (generated by scripts/gen-demo-data.mjs). */

export type DemoMissionType = "BUG_HEALING" | "MIGRATION";

export interface DemoEvent {
  id: number;
  kind: string;
  payload: Record<string, unknown>;
  ts: string;
}

export interface DemoAttempt {
  id: string;
  iteration: number;
  exit_code: number | null;
  fail_to_pass: number;
  pass_to_pass_broken: number;
  patch_lines: number;
  selected: boolean;
  patch: string;
}

export interface DemoUsage {
  model: string;
  prompt_tokens: number;
  completion_tokens: number;
  cost_usd: number;
}

export interface DemoRecording {
  recordingId: string;
  mission: {
    id: string;
    type: DemoMissionType;
    repo_url: string | null;
    git_ref: string | null;
    test_command: string | null;
    swe_instance_id: string | null;
    status: string;
    iteration: number;
    spend_usd: number;
    created_at: string;
    summary: Record<string, unknown>;
    diff: Array<{ path: string; original: string; modified: string; language: string }>;
  };
  attempts: DemoAttempt[];
  usage: DemoUsage[];
  events: DemoEvent[];
}

export interface ReplayMeta {
  id: string;
  title: string;
  type: DemoMissionType;
  repo_url: string | null;
  swe_instance_id: string | null;
  status: string;
  iterations: number;
  resolved: boolean;
  duration_s: number;
}
